COMMENT ON COLUMN CATEGORIES.PODCAST_ID IS 'The unique id of the podcast';
COMMENT ON COLUMN CATEGORIES.CATEGORY IS 'category of the podcast';
ALTER TABLE CATEGORIES MODIFY (CATEGORY ANNOTATIONS (ADD value_description 'commonsense evidence: This usually represents the topic of the podcast.'));
COMMENT ON COLUMN PODCASTS.PODCAST_ID IS 'The unique id of the podcast';
COMMENT ON COLUMN PODCASTS.ITUNES_ID IS 'The unique id of the itunes.';
COMMENT ON COLUMN PODCASTS.SLUG IS 'The slug of the podcast.';
ALTER TABLE PODCASTS MODIFY (SLUG ANNOTATIONS (ADD value_description 'commonsense evidence: It usually has the same name with the "title" column.'));
COMMENT ON COLUMN PODCASTS.ITUNES_URL IS 'The iTunes url of the podcast.';
ALTER TABLE PODCASTS MODIFY (ITUNES_URL ANNOTATIONS (ADD value_description 'commonsense evidence: Can visit the webpage of the podcast by clicking the itunes_url.'));
COMMENT ON COLUMN PODCASTS.TITLE IS 'The title of the podcast.';
ALTER TABLE PODCASTS MODIFY (TITLE ANNOTATIONS (ADD value_description 'commonsense evidence: It usually has a very similar name to the "slug" column.'));
COMMENT ON COLUMN REVIEWS.PODCAST_ID IS 'The unique id of the podcast';
COMMENT ON COLUMN REVIEWS.TITLE IS 'The title of the podcast review.';
ALTER TABLE REVIEWS MODIFY (TITLE ANNOTATIONS (ADD value_description 'commonsense evidence: This usually is the abstract of the whole review.'));
COMMENT ON COLUMN REVIEWS."CONTENT" IS 'The content of the podcast review.';
ALTER TABLE REVIEWS MODIFY ("CONTENT" ANNOTATIONS (ADD value_description 'commonsense evidence: This usually is the detailed explanation of the podcast review title.'));
COMMENT ON COLUMN REVIEWS.RATING IS 'The rating of the podcast review.';
ALTER TABLE REVIEWS MODIFY (RATING ANNOTATIONS (ADD value_description 'commonsense evidence: Allowed values: 0 to 5. This rating is highly related with "title" and "content".'));
COMMENT ON COLUMN REVIEWS.AUTHOR_ID IS 'The author id of the podcast review.';
COMMENT ON COLUMN REVIEWS.CREATED_AT IS 'The date and time of the podcast review creation.';
ALTER TABLE REVIEWS MODIFY (CREATED_AT ANNOTATIONS (ADD value_description 'In the format of "Date time". e.g., 2018-05-09T18:14:32-07:00'));
COMMENT ON COLUMN RUNS.RUN_AT IS 'The date and time of the podcast review creation.';
COMMENT ON COLUMN RUNS.MAX_ROWID IS 'The id of max row of this run.';
COMMENT ON COLUMN RUNS.REVIEWS_ADDED IS 'The number of reviews added in this run.';